#!/usr/bin/env bash
# Start BlenderLore tasks through Harbor's standard task runner.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"
[ -f .venv/bin/activate ] && source .venv/bin/activate
if [ -f .env ]; then
  set -a
  # shellcheck disable=SC1091
  source .env
  set +a
fi
# Load the runtime paths generated by install_blender_runtime.sh when present.
if [ -f /opt/blender/blenderlore-env.sh ]; then
  # shellcheck disable=SC1091
  source /opt/blender/blenderlore-env.sh
fi
export PYTHONPATH="$ROOT:${PYTHONPATH:-}"
: "${BLENDERLORE_JOBS_DIR:=$ROOT/../blenderlore-jobs}"
mkdir -p "$BLENDERLORE_JOBS_DIR"
delete_flag=(--no-delete)
for arg in "$@"; do
  case "$arg" in
    --delete|--no-delete)
      delete_flag=()
      break
      ;;
  esac
done
exec harbor run --jobs-dir "$BLENDERLORE_JOBS_DIR" "${delete_flag[@]}" "$@"
